1: /**
2:  * Browser-native image compression for the chat composer.
3:  *
4:  * Why
5:  * ---
6:  * Renderer-side (browser) compression keeps us off native deps (no sharp,
7:  * no canvas npm package) — `<canvas>.toBlob` is built into Electron's
8:  * Chromium and does the entire decode → resize → re-encode cycle for us.
9:  *
10:  * The engine has a hard policy (`packages/core/src/engine/image-policy.ts`)
11:  * that refuses any image over 2 MB. Without this step, a user pasting a
12:  * 4 MB screenshot would have their turn refused with a friendly error
13:  * but still need to compress manually. This step makes the friendly
14:  * refusal the *fallback*, not the common case.
15:  *
16:  * Strategy
17:  * --------
18:  * 1. If the original is already small (≤ TARGET_BYTES), pass through
19:  *    unchanged. We don't re-encode tiny PNGs into JPEGs lossily for
20:  *    nothing — that would visibly degrade screenshots of code.
21:  * 2. Otherwise, load into an <img>, draw onto a canvas with the long
22:  *    edge clamped to MAX_DIMENSION, and re-encode as JPEG at a fixed
23:  *    quality. Two re-encode attempts at progressively lower quality
24:  *    give a soft landing for unusually large inputs.
25:  * 3. If anything in the pipeline throws (HEIC the canvas can't decode,
26:  *    OOM, …), return the original — the engine policy will catch it
27:  *    later. Compression must never *lose* an image.
28:  *
29:  * Public surface is just `compressIfNeeded()`. Constants are inline +
30:  * exported for the tests under `compress.test.ts`.
31:  *
32:  * Animated GIF caveat: drawing a GIF to canvas freezes the first frame.
33:  * That's a one-way conversion. For now we still compress them when
34:  * oversized — preserving the bytes of a 5 MB GIF is the worse failure
35:  * (it would just be rejected by the engine anyway). A future change
36:  * could skip GIFs and surface a warning instead.
37:  */
38: 
39: import type { ImageAttachment } from "./attachments";
40: 
41: /**
42:  * Bytes below this we don't bother re-encoding. Matches the engine's
43:  * `IMAGE_LIMITS.maxBytesPerImage` (2 MB) so anything passing this gate
44:  * also passes the engine gate.
45:  *
46:  * Kept in sync manually because the renderer can't import from core
47:  * (different build target).
48:  */
49: export const TARGET_BYTES = 2 * 1024 * 1024;
50: 
51: /** Long-edge pixel cap. Matches engine's `IMAGE_TARGETS.targetMaxDimension`. */
52: export const MAX_DIMENSION = 2048;
53: 
54: /**
55:  * Image clarity level (provider-agnostic). Drives the long-edge cap so the user
56:  * trades fidelity for token cost. Replaces the old OpenAI-only low/high/original
57:  * knob: for OpenAI the engine still maps low→low / standard,high→high; for
58:  * Anthropic (no detail param — it just bills by pixels, ⌈w/28⌉×⌈h/28⌉) the
59:  * SAVING comes entirely from this renderer-side downscale before send.
60:  *   low      — 省钱: long edge ≤ 1024 (fewest tokens)
61:  *   standard — 1568 (old-model native cap; good cost/quality)
62:  *   high     — 2576 (Opus 4.7/4.8 high-res cap; full fidelity)
63:  */
64: export type ImageDetail = "low" | "standard" | "high";
65: 
66: const DETAIL_CAPS: Record<ImageDetail, number> = {
67:   low: 1024,
68:   standard: 1568,
69:   high: 2576,
70: };
71: 
72: /** Long-edge pixel cap for a clarity level. Unknown/undefined → high (no
73:  *  surprise downscale of someone who never opted in). */
74: export function capForDetail(detail: ImageDetail | undefined): number {
75:   return (detail && DETAIL_CAPS[detail]) || DETAIL_CAPS.high;
76: }
77: 
78: /**
79:  * Whether to downsample EVERY image (not just oversized ones). low/standard do
80:  * — that's how they actually cut tokens (a sub-2MB but 3000px screenshot still
81:  * costs ~4784 tokens on Opus). high preserves fidelity: compress only when over
82:  * the byte cap, exactly like the original behaviour.
83:  */
84: export function alwaysDownsample(detail: ImageDetail | undefined): boolean {
85:   return detail === "low" || detail === "standard";
86: }
87: 
88: /**
89:  * JPEG quality ladder. We try the first quality; if the result is still
90:  * over `TARGET_BYTES` we try the next one, and so on. Empirically two
91:  * steps land every screenshot we've thrown at it under the cap.
92:  */
93: const QUALITY_LADDER = [0.82, 0.7, 0.55];
94: 
95: /** MIME types we recompress as JPEG. Others pass through unchanged. */
96: const RECOMPRESSIBLE = new Set(["image/png", "image/jpeg", "image/jpg", "image/webp"]);
97: 
98: /**
99:  * Compress one ImageAttachment if it exceeds `TARGET_BYTES`. Returns a
100:  * possibly-new ImageAttachment (with updated dataUrl/size/mime/name) or
101:  * the original instance unchanged.
102:  *
103:  * The function is `async` because `Image.decode()` and `canvas.toBlob()`
104:  * both need it. It never rejects — failures fall back to the original.
105:  */
106: export async function compressIfNeeded(
107:   att: ImageAttachment,
108:   detail?: ImageDetail,
109: ): Promise<ImageAttachment> {
110:   // high/default: only touch oversized images (preserve fidelity). low/standard:
111:   // downsample every image to cut tokens, even when under the byte cap.
112:   if (att.size <= TARGET_BYTES && !alwaysDownsample(detail)) return att;
113:   if (!RECOMPRESSIBLE.has(att.mime)) return att;
114: 
115:   const cap = capForDetail(detail);
116:   try {
117:     const img = await loadImage(att.dataUrl);
118:     const { width, height } = scaledDimensions(
119:       img.naturalWidth,
120:       img.naturalHeight,
121:       cap,
122:     );
123:     // Already at/under the cap AND within bytes → nothing to gain, keep original
124:     // (avoids needlessly re-encoding a small PNG of code into lossy JPEG).
125:     if (width === img.naturalWidth && height === img.naturalHeight && att.size <= TARGET_BYTES) {
126:       return att;
127:     }
128:     const canvas = document.createElement("canvas");
129:     canvas.width = width;
130:     canvas.height = height;
131:     const ctx = canvas.getContext("2d");
132:     if (!ctx) return att;
133:     ctx.drawImage(img, 0, 0, width, height);
134: 
135:     for (const q of QUALITY_LADDER) {
136:       const blob = await canvasToBlob(canvas, "image/jpeg", q);
137:       if (!blob) continue;
138:       if (blob.size <= TARGET_BYTES || q === QUALITY_LADDER[QUALITY_LADDER.length - 1]) {
139:         const dataUrl = await blobToDataUrl(blob);
140:         return {
141:           ...att,
142:           mime: "image/jpeg",
143:           // Rename only the extension so the tooltip still shows where
144:           // the bytes came from. `a.png` → `a.png.jpg` is the convention
145:           // ImageMagick uses for non-destructive re-encodes.
146:           name: att.name.match(/\.jpe?g$/i) ? att.name : `${att.name}.jpg`,
147:           dataUrl,
148:           size: blob.size,
149:         };
150:       }
151:     }
152:     return att;
153:   } catch (err) {
154:     // Bubble up to console for triage but keep the original — the
155:     // engine's policy gate is the safety net.
156:     console.warn("[attachments] compress failed", err);
157:     return att;
158:   }
159: }
160: 
161: /**
162:  * Run `compressIfNeeded` on a batch in parallel. Order of the output
163:  * matches the input order so the renderer's attachment chips don't
164:  * shuffle when a single image takes longer to encode.
165:  */
166: export async function compressBatch(
167:   atts: ImageAttachment[],
168:   detail?: ImageDetail,
169: ): Promise<ImageAttachment[]> {
170:   return Promise.all(atts.map((a) => compressIfNeeded(a, detail)));
171: }
172: 
173: // ---------------------------------------------------------------- internals
174: 
175: function loadImage(src: string): Promise<HTMLImageElement> {
176:   return new Promise((resolve, reject) => {
177:     const img = new Image();
178:     img.onload = () => resolve(img);
179:     img.onerror = () => reject(new Error("image decode failed"));
180:     img.src = src;
181:   });
182: }
183: 
184: /**
185:  * Long-edge clamp that preserves aspect ratio. If the image is already
186:  * within the cap, returns its natural dimensions unchanged — important
187:  * so screenshots of code stay readable.
188:  */
189: export function scaledDimensions(
190:   w: number,
191:   h: number,
192:   cap: number,
193: ): { width: number; height: number } {
194:   if (w <= cap && h <= cap) return { width: w, height: h };
195:   if (w >= h) {
196:     return { width: cap, height: Math.round((h * cap) / w) };
197:   }
198:   return { width: Math.round((w * cap) / h), height: cap };
199: }
200: 
201: function canvasToBlob(
202:   canvas: HTMLCanvasElement,
203:   type: string,
204:   quality: number,
205: ): Promise<Blob | null> {
206:   return new Promise((resolve) => {
207:     canvas.toBlob((b) => resolve(b), type, quality);
208:   });
209: }
210: 
211: function blobToDataUrl(blob: Blob): Promise<string> {
212:   return new Promise((resolve, reject) => {
213:     const r = new FileReader();
214:     r.onload = () => resolve(String(r.result ?? ""));
215:     r.onerror = () => reject(new Error("FileReader failed"));
216:     r.readAsDataURL(blob);
217:   });
218: }
